  read:function(){ var p=this.p, c=calc(p); if(c.inf) return [['상의 위치 b','—','cm'],['배율 m','—',''],['상','맺히지 않음','','th']]; var am=Math.abs(c.m);
    return [['상의 위치 b',num(c.b,1),'cm','hl'],['배율 m',num(c.m,2),''],['상의 종류',c.real?'실상':'허상',''],['상의 방향',c.up?'정립':'도립',''],['상의 크기',am>1.005?'확대':am<0.995?'축소':'같은 크기','','th'],['상의 높이',num(Math.abs(c.hi),1),'cm'],['1/a + 1/b',num(1/p.a+1/c.b,4),'1/cm'],['1/f',num(1/p.f,4),'1/cm','ok']]; },
