  cols:[{k:'t',l:'온도 t',u:'℃',d:0},{k:'K',l:'절대 온도 T',u:'K',d:1},{k:'V',l:'부피 V',u:'mL',d:1}], gx:'t', gy:'V', fit:true,
  fitHint:function(m,b,x,y){ if(x==='t'&&y==='V'&&Math.abs(m)>1e-9) return F('부피가 0이 되는 온도 = {0} ℃ (절대 영도 −273.15 ℃)',fmt(-b/m,1)); if(x==='K'&&y==='V') return F('V ÷ T = {0} mL/K (일정)',fmt(m,4)); },
