    var lo=mt[1]-0.35*(mt[2]-mt[1]), hi=mt[2]+0.35*(mt[2]-mt[1]), bh=Math.min(Hh-120,260), bt=50, X=lx+22; var sy=function(t){ return bt+bh-clamp((t-lo)/(hi-lo),0,1)*bh; };
