  hint:'깊이 슬라이더를 움직여 암석의 변화를 보세요. 오른쪽 그림에 변화가 표시돼요.', noPlay:true,
  params:[{id:'rock',l:'처음 암석',type:'seg',opts:[['sed','퇴적물'],['ign','화성암'],['sedr','퇴적암'],['met','변성암']],val:'sedr'},{id:'d',l:'묻힌 깊이',min:0,max:60,step:0.5,val:15,u:'km',d:1,pre:[[0,'지표'],[5,'5'],[15,'15'],[40,'40']]},
    {id:'g',l:'지온 증가율',min:10,max:50,step:1,val:25,u:'℃/km',pre:[[15,'15'],[25,'25'],[40,'40']]}],
  cols:[{k:'d',l:'깊이',u:'km',d:1},{k:'T',l:'온도',u:'℃',d:0},{k:'P',l:'압력',u:'MPa',d:0}], gx:'d', gy:'T', fit:true,
  fitHint:function(m,b,x,y){ if(x==='d'&&y==='T') return F('기울기 {0} ℃/km가 지온 증가율, y절편 {1} ℃가 지표의 온도예요',fmt(m,1),fmt(b,0)); if(x==='d'&&y==='P') return F('기울기 {0} MPa/km가 깊이 1 km마다 늘어나는 압력이에요',fmt(m,1)); },
