  params:[{id:'iso',l:'방사성 원소',type:'seg',opts:[['c14','탄소-14'],['k40','칼륨-40'],['u238','우라늄-238']],val:'u238'},{id:'n',l:'지난 반감기 수',min:0,max:6,step:0.05,val:0,d:2,pre:[[0,'0'],[1,'1'],[2,'2'],[3,'3']]},{id:'N',l:'원자의 수',min:20,max:400,step:10,val:200}],
  cols:[{k:'n',l:'반감기 수',d:2},{k:'th',l:'이론 비율',u:'%',d:1},{k:'pc',l:'실제 비율',u:'%',d:1}], gx:'n', gy:'pc', join:true,
  reset:function(){ H.setP('n',0); },
  step:function(dt){ var n=Math.min(6,this.p.n+dt*0.35); H.setP('n',Math.round(n*1000)/1000); return n>=6?'done':null; },
  draw:function(g,W,Hh){ var p=this.p, c=calc(p), wd=wide(W,Hh), ar=wd?{l:10,t:30,w:W*0.42,h:Hh-60}:{l:10,t:28,w:W-20,h:Hh*0.4-30}, gr=wd?{l:W*0.42+60,t:30,w:W*0.58-80,h:Hh-90}:{l:50,t:Hh*0.4+10,w:W-70,h:Hh*0.6-56};
    var N=p.N, cols=Math.max(4,Math.round(Math.sqrt(N*ar.w/ar.h))), rows=Math.ceil(N/cols), cs=Math.min(ar.w/cols,ar.h/rows,30), ox=ar.l+(ar.w-cs*cols)/2, oy=ar.t;
    for(var i=0;i<N;i++){ var x=ox+(i%cols)*cs+cs/2, y=oy+Math.floor(i/cols)*cs+cs/2, alive=TAU[i]>p.n; H.dot(g,x,y,cs*0.36,alive?C.or:(TH.light?'#aab4cc':'#4a5570')); }
    tx(g,ISO[p.iso][0]+' → '+ISO[p.iso][1],ar.l,14,{size:12.5,w:700,c:TH.dim});
    var v=plot(g,gr,0,6,0,100,'지난 반감기 수','남은 모원소 (%)',{xs:1,ys:25}); fnPlot(g,v,function(x){ return 100*Math.pow(0.5,x); },C.vio,2.5); var st=[]; for(var k=0;k<=240;k++){ var nn=Math.min(p.n,6)*k/240, r=0; for(var j=0;j<N;j++) if(TAU[j]>nn) r++; st.push([v.sx(nn),v.sy(100*r/N)]); } H.line(g,st,C.fry,2.5);
    [1,2,3].forEach(function(n){ H.seg(g,v.sx(n),v.sy(0),v.sx(n),v.sy(100*Math.pow(0.5,n)),TH.dim,1,[3,4]); H.seg(g,v.sx(0),v.sy(100*Math.pow(0.5,n)),v.sx(n),v.sy(100*Math.pow(0.5,n)),TH.dim,1,[3,4]); tag(g,num(100*Math.pow(0.5,n),1)+'%',v.sx(n)+4,v.sy(100*Math.pow(0.5,n))-12,TH.dim); });
    H.dot(g,v.sx(p.n),v.sy(100*c.ex),6,C.vio,TH.stage); H.dot(g,v.sx(p.n),v.sy(100*c.fr),6,C.or,TH.stage); },
  read:function(){ var p=this.p, c=calc(p), ratio=c.fr>0?(1-c.fr)/c.fr:NaN; return [['반감기',sci(c.T12),'년'],['지난 시간',sci(c.age),'년','hl'],['남은 모원소 (이론)',num(c.ex*100,1),'%'],['남은 모원소 (실제)',num(c.fr*100,1),'%','th'],['모원소 : 자원소',c.fr>0?'1 : '+num(ratio,2):'—',''],['측정으로 구한 나이',isFinite(c.est)?sci(c.est):'—','년','ok']]; },
