/* ===================== 13. 종 다양성 비교 (중1 생물의 다양성) ===================== */
(function(){
var COL=['#ffc93c','#ff8a3d','#3fe08f','#4f9dff','#ff6b6b','#a78bfa','#38d1e0','#ff7ab6','#9aa3ba','#c7e04a'];
function counts(S,q,N){ var w=[],sum=0,i; for(i=0;i<S;i++){ w.push(Math.pow(q,i)); sum+=w[i]; } var c=w.map(function(x){ return Math.floor(N*x/sum); }), rest=N-c.reduce(function(a,b){ return a+b; },0);
  var fr=w.map(function(x,i){ return [N*x/sum-c[i],i]; }).sort(function(a,b){ return b[0]-a[0]; }); for(i=0;rest>0;i=(i+1)%S,rest--) c[fr[i][1]]++; return c; }
function idx(c,N){ var sp=0, sh=0, S=0; c.forEach(function(n){ if(n>0){ var q=n/N; sp+=q*q; sh-=q*Math.log(q); S++; } }); return {D:1-sp, H:sh, S:S, J:S>1?sh/Math.log(S):1}; }
function panel(g,r,c,N,title){ var ix=idx(c,N), dh=r.h*0.42; tx(g,title,r.l+6,r.t+10,{size:14,w:800,c:C.fry});
  var cols=Math.ceil(Math.sqrt(N*(r.w-10)/dh)), rows=Math.ceil(N/cols), cs=Math.min((r.w-12)/cols,dh/rows), k=0, ox=r.l+6, oy=r.t+26;
  for(var s=0;s<c.length;s++) for(var j=0;j<c[s];j++,k++) H.dot(g,ox+(k%cols+0.5)*cs,oy+(Math.floor(k/cols)+0.5)*cs,cs*0.38,COL[s]);
  var by=oy+rows*cs+14, bh=r.t+r.h-by-72, mx=Math.max.apply(null,c.concat([1])), bw=Math.min(36,(r.w-16)/Math.max(1,c.length)-4);
  c.forEach(function(n,i){ var h=bh*n/mx, x=r.l+8+i*(bw+4); g.fillStyle=COL[i]; g.fillRect(x,by+bh-h,bw,h); H.text(g,String(n),x+bw/2,by+bh-h-8,{al:'center',size:11,w:700,c:TH.dim}); });
  H.seg(g,r.l+6,by+bh,r.l+r.w-6,by+bh,TH.dim,1.5);
  var ty=by+bh+16; tx(g,F('종 수 {0} · 개체 수 {1}',ix.S,N),r.l+6,ty,{size:12.5,w:700,c:TH.text}); tx(g,'심프슨 다양도 '+num(ix.D,2),r.l+6,ty+20,{size:12.5,w:700,c:C.cyan}); tx(g,'샤논 지수 '+num(ix.H,2),r.l+6,ty+38,{size:12.5,w:700,c:C.vio}); }
var E={id:'s1_diversity', cat:'sci', icon:'🌳', name:'종 다양성 비교', desc:'두 숲의 종 수와 고른 정도로 생물 다양성 지수 계산하기',
  info:'생물 다양성은 종이 얼마나 많은지(종 수)와 각 종이 얼마나 고르게 섞여 있는지(균등도)로 결정돼요. 개체 수가 같아도 한 종이 대부분을 차지하면 다양성이 낮아요. 심프슨 다양도는 1 − Σpᵢ²(서로 다른 종을 뽑을 확률), 샤논 지수는 −Σpᵢ ln pᵢ로 구해요. 네 종이 똑같이 있으면 심프슨 다양도는 0.75, 샤논 지수는 ln 4 = 1.39예요.',
  tries:['숲 A를 4종, 고른 정도 1.0으로 하면 심프슨 다양도가 얼마인가요? (0.75가 나와요)','종 수는 같게 두고 고른 정도만 낮추면 다양도가 어떻게 변하나요?','종 수가 적어도 고르게 섞인 숲과 종 수가 많아도 한 종이 우세한 숲 중 어느 쪽이 더 다양한가요?','개체 수를 바꾸어도 비율이 같으면 지수가 같은지 확인해 보세요'],
  hint:'점 하나는 개체 한 마리이고 색깔은 종을 뜻해요.', noPlay:true,
  params:[{id:'N',l:'조사한 개체 수',min:50,max:300,step:10,val:100},{id:'S1',l:'숲 A의 종 수',min:1,max:10,step:1,val:4},{id:'q1',l:'숲 A의 고른 정도 (1이면 똑같이)',min:0.2,max:1,step:0.05,val:1,d:2},
    {id:'S2',l:'숲 B의 종 수',min:1,max:10,step:1,val:8},{id:'q2',l:'숲 B의 고른 정도 (1이면 똑같이)',min:0.2,max:1,step:0.05,val:0.5,d:2}],
  cols:[{k:'S1',l:'숲 A 종 수',d:0},{k:'q1',l:'숲 A 고른 정도',d:2},{k:'DA',l:'숲 A 심프슨 다양도',d:3},{k:'HA',l:'숲 A 샤논 지수',d:3},{k:'DB',l:'숲 B 심프슨 다양도',d:3}], gx:'S1', gy:'DA',
  reset:function(){},
  draw:function(g,W,Hh){ var p=this.p, c1=counts(p.S1,p.q1,p.N), c2=counts(p.S2,p.q2,p.N), wd=W>=Hh*1.1; if(wd){ panel(g,{l:4,t:4,w:W/2-8,h:Hh-8},c1,p.N,'숲 A'); panel(g,{l:W/2+4,t:4,w:W/2-8,h:Hh-8},c2,p.N,'숲 B'); } else { panel(g,{l:4,t:2,w:W-8,h:Hh/2-4},c1,p.N,'숲 A'); panel(g,{l:4,t:Hh/2+2,w:W-8,h:Hh/2-4},c2,p.N,'숲 B'); } },
  read:function(){ var p=this.p, a=idx(counts(p.S1,p.q1,p.N),p.N), b=idx(counts(p.S2,p.q2,p.N),p.N); return [['숲 A 종 수',String(a.S),'종'],['숲 A 심프슨 다양도',num(a.D,3),'','hl'],['숲 A 샤논 지수',num(a.H,3),''],['숲 A 균등도',num(a.J,2),''],['숲 B 종 수',String(b.S),'종'],['숲 B 심프슨 다양도',num(b.D,3),'','hl'],['숲 B 샤논 지수',num(b.H,3),''],['숲 B 균등도',num(b.J,2),''],['더 다양한 숲',Math.abs(a.D-b.D)<0.0005?'비슷해요':a.D>b.D?'숲 A':'숲 B','','th']]; },
  record:function(){ var p=this.p, a=idx(counts(p.S1,p.q1,p.N),p.N), b=idx(counts(p.S2,p.q2,p.N),p.N); return {S1:p.S1, q1:p.q1, DA:a.D, HA:a.H, DB:b.D}; },
  ai:function(){ var p=this.p, a=idx(counts(p.S1,p.q1,p.N),p.N), b=idx(counts(p.S2,p.q2,p.N),p.N); return 'Species diversity of two forests with '+p.N+' individuals each. Forest A: '+p.S1+' species, evenness '+p.q1+', Simpson diversity 1-sum(p^2) = '+fmt(a.D,3)+', Shannon H = '+fmt(a.H,3)+'. Forest B: '+p.S2+' species, evenness '+p.q2+', Simpson '+fmt(b.D,3)+', Shannon '+fmt(b.H,3)+'.'; }
};
LAB.add(E);
})();

