  record:function(){ var c=calc(this.p); return {c1:c.c1, Tf:c.Tf, Q:Math.abs(c.Q)}; },
  ai:function(){ var p=this.p, c=calc(p); return 'Thermal equilibrium: '+p.w1+' g of '+p.m1+' (c = '+c.c1+' J/gK) at '+p.t1+' C mixed with '+p.w2+' g of '+p.m2+' (c = '+c.c2+') at '+p.t2+' C. Final temperature '+fmt(c.Tf,2)+' C; heat transferred '+fmt(Math.abs(c.Q),0)+' J.'; }
