    S.pos=[mx,my]; S.c=[cx,cy];
    var vr=wd?{l:ar.w,t:0,w:W-ar.w,h:Hh}:{l:0,t:ar.h,w:W,h:Hh-ar.h}, dc=[vr.l+vr.w/2,vr.t+vr.h*0.42], dr=Math.min(vr.w*0.34,vr.h*0.3), k=(1-Math.cos(a))/2;
    g.beginPath(); g.arc(dc[0],dc[1],dr,0,TAU); g.fillStyle=TH.light?'#c9ccd8':'#23262f'; g.fill(); var wax=p.a<=180;
