  hint:'시작을 누르면 하루가 빠르게 흘러요.', speed:true, playLabel:'하루 지나기',
  params:[{id:'t',l:'시각',min:0,max:24,step:0.25,val:14,u:'시',d:2,pre:[[2,'02시'],[8,'08시'],[14,'14시'],[20,'20시']]},{id:'aL',l:'육지의 일교차 크기',min:2,max:10,step:0.5,val:6,u:'℃',d:1},{id:'aS',l:'바다의 일교차 크기',min:0.5,max:6,step:0.5,val:1,u:'℃',d:1}],
  cols:[{k:'t',l:'시각',u:'시',d:2},{k:'tl',l:'육지 온도',u:'℃',d:1},{k:'ts',l:'바다 온도',u:'℃',d:1},{k:'w',l:'바람 (바다→육지 +)',u:'m/s',d:2}], gx:'t', gy:'w', join:true,
