  tries:['번호를 바꿔 가며 은하의 거리, 후퇴 속도, 적색 편이를 표에 기록해 보세요','가장 먼 은하의 후퇴 속도는 가장 가까운 은하의 몇 배인가요?','자료로 구한 H₀가 처음 값과 비슷한가요? 관측 오차를 키우면 어떻게 되나요?','H₀를 50과 100으로 바꾸면 우주의 나이는 각각 얼마가 되나요? (약 196억 년, 98억 년)'],
  hint:'은하 번호를 바꿔 스펙트럼의 이동을 보고, 기록해서 그래프로 확인하세요.', noPlay:true,
  params:[{id:'H0',l:'허블 상수 H₀',min:40,max:110,step:1,val:70,u:'km/s/Mpc',pre:[[50,'50'],[70,'70'],[100,'100']]},{id:'sig',l:'관측 오차 (속도)',min:0,max:1500,step:50,val:400,u:'km/s'},{id:'n',l:'관측하는 은하 번호',min:1,max:N,step:1,val:6}],
  cols:[{k:'d',l:'거리 d',u:'Mpc',d:0},{k:'v',l:'후퇴 속도 v',u:'km/s',d:0},{k:'z',l:'적색 편이 z',d:4}], gx:'d', gy:'v', fit:true, join:false,
  fitHint:function(m,b,x,y){ if(x==='d'&&y==='v') return F('기울기 {0} km/s/Mpc = 허블 상수 H₀',fmt(m,1)); },
  reset:function(){},
